cssStarter:
:root{--accent:#ffee02;--ink:#000000;--body:#727272;--surface:#ffffff;--surface-alt:#f4f4f4;--dark:#000000;--dark-2:#171715;--line:#c1c1c1;--container:1280px;--gutter:32px;--section-y:120px}
body{font-family:'DM Sans',sans-serif;font-size:16px;line-height:1.88;color:var(--body)}
.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
.eyebrow{font-family:'DM Sans',sans-serif;font-size:14px;font-weight:700;line-height:1.71;text-transform:uppercase;color:var(--body);margin-bottom:10px}
.eyebrow-brush{display:inline-block;font-family:'Unbounded',sans-serif;font-size:16px;font-weight:500;text-transform:uppercase;color:#000;background:var(--accent);padding:6px 60px;clip-path:polygon(3% 10%,97% 0,100% 55%,96% 100%,2% 92%,0 40%);margin-bottom:27px}
h1{font-family:'Unbounded',sans-serif;font-size:64px;font-weight:700;line-height:1.25;color:#fff;margin-bottom:30px}
h2{font-family:'Unbounded',sans-serif;font-size:48px;font-weight:500;line-height:1.2;color:var(--ink);margin:0}
h4{font-family:'Unbounded',sans-serif;font-size:20px;font-weight:500;line-height:1.4;color:var(--ink)}
.btn{display:inline-flex;align-items:center;justify-content:center;padding:19px 51px;border-radius:0;font-size:14px;font-weight:600;letter-spacing:.7px;text-transform:uppercase;background:var(--accent);color:#000}
.btn-outline{background:#fff;border:2px solid var(--accent);padding:15px 30px;font-size:16px;font-weight:700;text-transform:none;letter-spacing:0}
.card{border:1px solid var(--line);background:#fff}
.photo-ring{border-radius:50%;outline:1px solid var(--accent);outline-offset:14px}
@media(max-width:768px){:root{--section-y:72px}h1{font-size:38px}h2{font-size:30px}}
